  });

  @override
  State<FeedPage> createState() => _FeedPageState();
}

class _FeedPageState extends State<FeedPage> {
  final ScrollController _scrollController = ScrollController();
  final List<Post> _posts = [];

  bool _isInitialLoading = true;
  bool _isPaginating = false;
  bool _isNavigating = false;

  int _page = 1;
  final int _pageSize = 10;
  int _feedVersion = DateTime.now().millisecondsSinceEpoch;

  final Random _random = Random();

  final List<String> _usernames = const [
    'pixelfox',
    'noirwaves',
    'cityframe',
    'lostsignal',
    'midnightcafe',
    'staticdreams',
    'retroflora',
    'filmgrain',
    'dustyvinyl',
    'bluehorizon',
    'cloudparlor',
    'shadownote',
  ];

  final List<String> _captions = const [
    'A quiet moment somewhere far away.',
    'Chasing light and losing track of time.',
    'Nothing special, just liked the colors.',
    'This one felt like a movie frame.',
    'Tiny details make the whole day better.',
    'Collected another soft memory.',
    'Somewhere between noise and peace.',
    'The kind of day that writes itself.',
    'A little texture, a little chaos.',
    'Could stare at this for hours.',
    'Just passing through.',
    'The feed needed this vibe.',
  ];

  final List<String> _locations = const [
    'Istanbul',
    'Amsterdam',
    'Berlin',
    'Tokyo',
    'New York',
    'Paris',
    'Seoul',
    'Copenhagen',
    'Prague',
    'Lisbon',
    'Vienna',
    'Oslo',
  ];

  final List<ChatThread> _threads = [
    ChatThread(
      user: ChatUser(
        id: 'u1',
        username: 'noirwaves',
        avatarUrl: 'https://picsum.photos/seed/dm_u1/100/100',
        isOnline: true,
      ),
      messages: [
        ChatMessage(
          id: 'm1',
          text: 'yo did you post the new cover yet?',
          isMe: false,
          timestamp: DateTime.now().subtract(const Duration(minutes: 25)),
        ),
        ChatMessage(
          id: 'm2',
          text: 'not yet, still tweaking the mix a bit',
          isMe: true,
          timestamp: DateTime.now().subtract(const Duration(minutes: 22)),
        ),
        ChatMessage(
          id: 'm3',
          text: 'send it when it is up',
          isMe: false,
          timestamp: DateTime.now().subtract(const Duration(minutes: 19)),
        ),
      ],
    ),
    ChatThread(
      user: ChatUser(
        id: 'u2',
        username: 'filmgrain',
        avatarUrl: 'https://picsum.photos/seed/dm_u2/100/100',
        isOnline: false,
      ),
      messages: [
        ChatMessage(
          id: 'm4',
          text: 'that last snippet looked great',
          isMe: false,
          timestamp: DateTime.now().subtract(const Duration(hours: 2)),
        ),
      ],
    ),
    ChatThread(
      user: ChatUser(
        id: 'u3',
        username: 'cloudparlor',
        avatarUrl: 'https://picsum.photos/seed/dm_u3/100/100',
        isOnline: true,
      ),
      messages: [
        ChatMessage(
          id: 'm5',
          text: 'want to collab on a dreamy acoustic track?',
          isMe: false,
          timestamp: DateTime.now().subtract(const Duration(hours: 5)),
        ),
        ChatMessage(
          id: 'm6',
          text: 'yeah, send the key and bpm',
          isMe: true,
          timestamp: DateTime.now().subtract(const Duration(hours: 4, minutes: 50)),
        ),
      ],
    ),
  ];

  @override
  void initState() {
    super.initState();
    _loadInitial();
    _scrollController.addListener(_onScroll);
  }

  @override
  void dispose() {
    _scrollController
      ..removeListener(_onScroll)
      ..dispose();
    super.dispose();
  }

  Future<void> _loadInitial() async {
    setState(() {
      _isInitialLoading = true;
      _posts.clear();
      _page = 1;
    });

    final newPosts = await _fakeFetchPosts(page: _page, pageSize: _pageSize);

    if (!mounted) return;

    setState(() {
      _posts.addAll(newPosts);
      _isInitialLoading = false;
    });
  }

  Future<void> _refreshFeed() async {
    _feedVersion = DateTime.now().millisecondsSinceEpoch;

    setState(() {
      _page = 1;
      _posts.clear();
    });

    final refreshedPosts =
        await _fakeFetchPosts(page: _page, pageSize: _pageSize);

    if (!mounted) return;

    setState(() {
      _posts.addAll(refreshedPosts);
    });
  }

  void _onScroll() {
    final position = _scrollController.position;
    if (position.pixels >= position.maxScrollExtent - 500) {
      _loadMore();
    }
  }

  Future<void> _loadMore() async {
    if (_isPaginating || _isInitialLoading) return;

    setState(() {
      _isPaginating = true;
    });

    final nextPage = _page + 1;
    final morePosts =
        await _fakeFetchPosts(page: nextPage, pageSize: _pageSize);

    if (!mounted) return;

    setState(() {
      _page = nextPage;
      _posts.addAll(morePosts);
      _isPaginating = false;
    });
  }

  Future<List<Post>> _fakeFetchPosts({
    required int page,
    required int pageSize,
  }) async {
    await Future.delayed(const Duration(milliseconds: 850));

    final startIndex = (page - 1) * pageSize;

    return List.generate(pageSize, (index) {
      final globalIndex = startIndex + index;
      final seed = 'feed_${_feedVersion}_p${page}_i$globalIndex';

      return Post(
        id: 'post_$seed',
        username: _usernames[globalIndex % _usernames.length],
        location: _locations[globalIndex % _locations.length],
        caption: _captions[globalIndex % _captions.length],
        avatarUrl: 'https://picsum.photos/seed/avatar_$seed/100/100',
        imageUrl: 'https://picsum.photos/seed/$seed/900/1200',
        likes: 80 + _random.nextInt(5000),
        minutesAgo: 1 + _random.nextInt(300),
      );
    });
  }

  Future<void> _openCameraPage() async {
    if (_isNavigating) return;
    _isNavigating = true;
    try {
      await Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => CameraPage(cameras: widget.cameras),
        ),
      );
    } finally {
      _isNavigating = false;
    }
  }

  Future<void> _openMessagesPage() async {
    if (_isNavigating) return;
    _isNavigating = true;
    try {
      await Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => MessagesPage(
            initialThreads: _threads,
          ),
        ),
      );
    } finally {
      _isNavigating = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.translucent,
      onHorizontalDragEnd: (details) {
        final velocity = details.primaryVelocity ?? 0;

        if (velocity < -400) {
          _openCameraPage();
        } else if (velocity > 400) {
          _openMessagesPage();
        }
      },
      child: Scaffold(
        appBar: AppBar(
          elevation: 0,
          surfaceTintColor: Colors.white,
          backgroundColor: Colors.white,
          title: const Text(
            'Instagram',
            style: TextStyle(
              fontWeight: FontWeight.w700,
              fontSize: 28,
              color: Colors.black,
            ),
          ),
          actions: [
            IconButton(
              onPressed: _openCameraPage,
              icon: const Icon(Icons.camera_alt_outlined, color: Colors.black),
            ),
            IconButton(
              onPressed: _openMessagesPage,
              icon: const Icon(Icons.send_outlined, color: Colors.black),
            ),
          ],
        ),
        body: _isInitialLoading
            ? const Center(child: CircularProgressIndicator())
            : RefreshIndicator(
                onRefresh: _refreshFeed,
                child: ListView.builder(
                  controller: _scrollController,
                  physics: const AlwaysScrollableScrollPhysics(),
                  itemCount: _posts.length + (_isPaginating ? 1 : 0),
                  itemBuilder: (context, index) {
                    if (index >= _posts.length) {
                      return const Padding(
                        padding: EdgeInsets.symmetric(vertical: 24),
                        child: Center(child: CircularProgressIndicator()),
                      );
                    }
                    return PostCard(post: _posts[index]);
                  },
                ),
              ),
        bottomNavigationBar: NavigationBar(
          backgroundColor: Colors.white,
          indicatorColor: Colors.transparent,
          selectedIndex: 0,
          destinations: const [
            NavigationDestination(
              icon: Icon(Icons.home_filled, color: Colors.black),
              label: '',
            ),
            NavigationDestination(
              icon: Icon(Icons.search, color: Colors.black),
              label: '',
            ),
            NavigationDestination(
              icon: Icon(Icons.add_box_outlined, color: Colors.black),
              label: '',
            ),
            NavigationDestination(
              icon: Icon(Icons.movie_creation_outlined, color: Colors.black),
              label: '',
            ),
            NavigationDestination(
              icon: Icon(Icons.person_outline, color: Colors.black),
              label: '',
            ),
          ],
        ),
      ),
    );
  }
}

class CameraPage extends StatefulWidget {
  final List<CameraDescription> cameras;

  const CameraPage({
    super.key,
    required this.cameras,
  });

  @override
  State<CameraPage> createState() => _CameraPageState();
}

class _CameraPageState extends State<CameraPage> {
  CameraController? _controller;
  bool _isReady = false;
  String? _error;
  int _selectedCameraIndex = 0;

  @override
  void initState() {
    super.initState();
    _setupCamera();
  }

  Future<void> _setupCamera() async {
    if (widget.cameras.isEmpty) {
      setState(() {
        _error = 'No camera available on this device.';
      });
      return;
    }

    await _initializeCamera(widget.cameras[_selectedCameraIndex]);
  }

  Future<void> _initializeCamera(CameraDescription description) async {
    final oldController = _controller;

    final controller = CameraController(
      description,
      ResolutionPreset.medium,
      enableAudio: false,
    );

    try {
      await oldController?.dispose();

      _controller = controller;
      await controller.initialize();

      if (!mounted) return;

      setState(() {
        _isReady = true;
        _error = null;
      });
    } catch (e) {
      await controller.dispose();

      if (!mounted) return;

      setState(() {
        _isReady = false;
        _error = 'Failed to initialize camera: $e';
      });
    }
  }

  Future<void> _switchCamera() async {
    if (widget.cameras.length < 2) return;

    setState(() {
      _isReady = false;
    });

    _selectedCameraIndex =
        (_selectedCameraIndex + 1) % widget.cameras.length;

    await _initializeCamera(widget.cameras[_selectedCameraIndex]);
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = _controller;

    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onHorizontalDragEnd: (details) {
        final velocity = details.primaryVelocity ?? 0;
        if (velocity > 400) {
          Navigator.of(context).maybePop();
        }
      },
      child: Scaffold(
        backgroundColor: Colors.black,
        appBar: AppBar(
          backgroundColor: Colors.black,
          foregroundColor: Colors.white,
          title: const Text('Camera'),
        ),
        body: Stack(
          children: [
            Positioned.fill(
              child: Builder(
                builder: (context) {
                  if (_error != null) {
                    return Center(
                      child: Padding(
                        padding: const EdgeInsets.all(24),
                        child: Text(
                          _error!,
                          textAlign: TextAlign.center,
                          style: const TextStyle(color: Colors.white),
                        ),
                      ),
                    );
                  }

                  if (!_isReady ||
                      controller == null ||
                      !controller.value.isInitialized) {
                    return const Center(
                      child: CircularProgressIndicator(color: Colors.white),
                    );
                  }

                  return CameraPreview(controller);
                },
              ),
            ),
            Positioned(
              left: 0,
              right: 0,
              bottom: 24,
              child: SafeArea(
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceEvenly,
                  children: [
                    IconButton(
                      onPressed: () => Navigator.of(context).maybePop(),
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                    ),
                    Container(
                      width: 74,
                      height: 74,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(color: Colors.white, width: 4),
                      ),
                    ),
                    IconButton(
                      onPressed: _switchCamera,
                      icon: const Icon(Icons.cameraswitch, color: Colors.white),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class MessagesPage extends StatefulWidget {
  final List<ChatThread> initialThreads;

  const MessagesPage({
    super.key,
    required this.initialThreads,
  });

  @override
  State<MessagesPage> createState() => _MessagesPageState();
}

class _MessagesPageState extends State<MessagesPage> {
  late List<ChatThread> _threads;

  @override
  void initState() {
    super.initState();
    _threads = widget.initialThreads
        .map((t) => t.copyWith(messages: List<ChatMessage>.from(t.messages)))
        .toList();
  }

  void _updateThread(ChatThread updatedThread) {
    setState(() {
      final index = _threads.indexWhere((t) => t.user.id == updatedThread.user.id);
      if (index != -1) {
        _threads[index] = updatedThread;
      }
      _threads.sort((a, b) {
        final aTime = a.messages.isNotEmpty
            ? a.messages.last.timestamp
            : DateTime.fromMillisecondsSinceEpoch(0);
        final bTime = b.messages.isNotEmpty
            ? b.messages.last.timestamp
            : DateTime.fromMillisecondsSinceEpoch(0);
        return bTime.compareTo(aTime);
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onHorizontalDragEnd: (details) {
        final velocity = details.primaryVelocity ?? 0;
        if (velocity < -400) {
          Navigator.of(context).maybePop();
        }
      },
      child: Scaffold(
        backgroundColor: Colors.white,
        appBar: AppBar(
          title: const Text(
            'Direct Messages',
            style: TextStyle(fontWeight: FontWeight.w700),
          ),
          backgroundColor: Colors.white,
          surfaceTintColor: Colors.white,
        ),
        body: ListView.separated(
          itemCount: _threads.length,
          separatorBuilder: (_, __) => const Divider(height: 1),
          itemBuilder: (context, index) {
            final thread = _threads[index];
            final lastMessage =
                thread.messages.isNotEmpty ? thread.messages.last.text : 'Say hi';
            final lastTime = thread.messages.isNotEmpty
                ? _formatChatTime(thread.messages.last.timestamp)
                : '';

            return ListTile(
              onTap: () async {
                final updated = await Navigator.of(context).push<ChatThread>(
                  MaterialPageRoute(
                    builder: (_) => ChatPage(thread: thread),
                  ),
                );

                if (updated != null) {
                  _updateThread(updated);
                }
              },
              contentPadding:
                  const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
              leading: Stack(
                children: [
                  CircleAvatar(
                    radius: 28,
                    backgroundImage: NetworkImage(thread.user.avatarUrl),
                  ),
                  if (thread.user.isOnline)
                    Positioned(
                      right: 0,
                      bottom: 0,
                      child: Container(
                        width: 14,
                        height: 14,
                        decoration: BoxDecoration(
                          color: Colors.green,
                          shape: BoxShape.circle,
                          border: Border.all(color: Colors.white, width: 2),
                        ),
                      ),
                    ),
                ],
              ),
              title: Text(
                thread.user.username,
                style: const TextStyle(fontWeight: FontWeight.w700),
              ),
              subtitle: Text(
                lastMessage,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
              trailing: Text(
                lastTime,
                style: TextStyle(color: Colors.grey.shade600, fontSize: 12),
              ),
            );
          },
        ),
      ),
    );
  }
}

class ChatPage extends StatefulWidget {
  final ChatThread thread;

  const ChatPage({
    super.key,
    required this.thread,
  });

  @override
  State<ChatPage> createState() => _ChatPageState();
}

class _ChatPageState extends State<ChatPage> {
  late ChatThread _thread;
  final TextEditingController _controller = TextEditingController();
  final ScrollController _scrollController = ScrollController();
  final Random _random = Random();

  final List<String> _autoReplies = const [
    'nice',
    'that sounds good to me',
    'send it over',
    'lol yeah',
    'I was literally thinking the same thing',
    'give me a minute',
    'that is actually hard',
    'let’s do it',
    'wait that sounds amazing',
    'I am in',
    'show me the demo',
    'can you send the file',
  ];

  @override
  void initState() {
    super.initState();
    _thread = widget.thread.copyWith(
      messages: List<ChatMessage>.from(widget.thread.messages),
    );

    WidgetsBinding.instance.addPostFrameCallback((_) {
      _jumpToBottom();
    });
  }

  @override
  void dispose() {
    _controller.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  void _jumpToBottom() {
    if (!_scrollController.hasClients) return;
    _scrollController.jumpTo(
      _scrollController.position.maxScrollExtent,
    );
  }

  Future<void> _animateToBottom() async {
    await Future.delayed(const Duration(milliseconds: 50));
    if (!_scrollController.hasClients) return;
    await _scrollController.animateTo(
      _scrollController.position.maxScrollExtent + 80,
      duration: const Duration(milliseconds: 250),
      curve: Curves.easeOut,
    );
  }

  Future<void> _sendMessage() async {
    final text = _controller.text.trim();
    if (text.isEmpty) return;

    final newMessage = ChatMessage(
      id: DateTime.now().microsecondsSinceEpoch.toString(),
      text: text,
      isMe: true,
      timestamp: DateTime.now(),
    );

    setState(() {
      _thread = _thread.copyWith(
        messages: [..._thread.messages, newMessage],
      );
      _controller.clear();
    });

    await _animateToBottom();

    Future.delayed(
      Duration(milliseconds: 900 + _random.nextInt(1200)),
      () {
        if (!mounted) return;

        final reply = ChatMessage(
          id: DateTime.now().microsecondsSinceEpoch.toString(),
          text: _autoReplies[_random.nextInt(_autoReplies.length)],
          isMe: false,
          timestamp: DateTime.now(),
        );

        setState(() {
          _thread = _thread.copyWith(
            messages: [..._thread.messages, reply],
          );
        });

        _animateToBottom();
      },
    );
  }

  void _popWithResult() {
    Navigator.of(context).pop(_thread);
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onHorizontalDragEnd: (details) {
        final velocity = details.primaryVelocity ?? 0;
        if (velocity < -400) {
          _popWithResult();
        }
      },
      child: WillPopScope(
        onWillPop: () async {
          _popWithResult();
          return false;
        },
        child: Scaffold(
          backgroundColor: Colors.white,
          appBar: AppBar(
            backgroundColor: Colors.white,
            surfaceTintColor: Colors.white,
            leading: IconButton(
              onPressed: _popWithResult,
              icon: const Icon(Icons.arrow_back),
            ),
            titleSpacing: 0,
            title: Row(
              children: [
                CircleAvatar(
                  radius: 18,
                  backgroundImage: NetworkImage(_thread.user.avatarUrl),
                ),
                const SizedBox(width: 10),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      _thread.user.username,
                      style: const TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 15,
                      ),
                    ),
                    Text(
                      _thread.user.isOnline ? 'Active now' : 'Offline',
                      style: TextStyle(
                        fontSize: 12,
                        color: Colors.grey.shade600,
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
          body: Column(
            children: [
              Expanded(
                child: ListView.builder(
                  controller: _scrollController,
                  padding:
                      const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
                  itemCount: _thread.messages.length,
                  itemBuilder: (context, index) {
                    final message = _thread.messages[index];
                    return Align(
                      alignment: message.isMe
                          ? Alignment.centerRight
                          : Alignment.centerLeft,
                      child: Container(
                        margin: const EdgeInsets.symmetric(vertical: 4),
                        padding: const EdgeInsets.symmetric(
                          horizontal: 14,
                          vertical: 10,
                        ),
                        constraints: BoxConstraints(
                          maxWidth: MediaQuery.of(context).size.width * 0.72,
                        ),
                        decoration: BoxDecoration(
                          color: message.isMe
                              ? Colors.blueAccent
                              : Colors.grey.shade200,
                          borderRadius: BorderRadius.circular(18),
                        ),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              message.text,
                              style: TextStyle(
                                color: message.isMe
                                    ? Colors.white
                                    : Colors.black,
                              ),
                            ),
                            const SizedBox(height: 4),
                            Text(
                              _formatMessageTime(message.timestamp),
                              style: TextStyle(
                                fontSize: 11,
                                color: message.isMe
                                    ? Colors.white70
                                    : Colors.grey.shade600,
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  },
                ),
              ),
              SafeArea(
                top: false,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
                  child: Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: _controller,
                          minLines: 1,
                          maxLines: 5,
                          textInputAction: TextInputAction.send,
                          onSubmitted: (_) => _sendMessage(),
                          decoration: InputDecoration(
                            hintText: 'Message...',
                            filled: true,
                            fillColor: Colors.grey.shade100,
                            contentPadding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 12,
                            ),
                            border: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(24),
                              borderSide: BorderSide.none,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      CircleAvatar(
                        radius: 24,
                        backgroundColor: Colors.blueAccent,
                        child: IconButton(
                          onPressed: _sendMessage,
                          icon: const Icon(
                            Icons.send,
                            color: Colors.white,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

