        isSentByMe: false,
        timestamp: DateTime.now().subtract(const Duration(minutes: 5)),
        senderName: 'Sarah Johnson',
        senderImage: 'https://picsum.photos/id/101/50/50',
      ),
    ];

    _conversations['user3'] = [
      Message(
        id: '1',
