  void _sendMessage() {
    if (_messageController.text.trim().isEmpty) return;

    final newMessage = Message(
      id: DateTime.now().millisecondsSinceEpoch.toString(),
      text: _messageController.text.trim(),
      isSentByMe: true,
      timestamp: DateTime.now(),
      senderName: 'Me',
      senderImage: '',
    );

    _messages.add(newMessage);
    _conversations[_currentConversation]!.add(newMessage);
    _messageController.clear();
    setState(() {});

    // Simulate reply after 2 seconds
    Future.delayed(const Duration(seconds: 2), () {
      if (_showMessagesView && _currentConversation != null) {
        final replyMessage = Message(
          id: DateTime.now().millisecondsSinceEpoch.toString(),
          text: _getAutoReply(),
          isSentByMe: false,
          timestamp: DateTime.now(),
          senderName: _getSenderName(_currentConversation!),
          senderImage: _getSenderImage(_currentConversation!),
        );
        _messages.add(replyMessage);
        _conversations[_currentConversation]!.add(replyMessage);
        setState(() {});
      }
    });
  }

  String _getAutoReply() {
    final List<String> replies = [
