      id: json['id'].toString(),
      author: 'user_${json['author'] ?? json['id']}',
      downloadUrl: json['download_url'] ?? json['url'],
      likesCount: (int.parse(json['id'].toString()) % 500) + 100,
      commentsCount: (int.parse(json['id'].toString()) % 50) + 5,
      caption: _getRandomCaption(int.parse(json['id'].toString())),
      timeAgo: '${(int.parse(json['id'].toString()) % 23) + 1} HOURS AGO',
    );
  }

  static String _getRandomCaption(int seed) {
    List<String> captions = [
      'Amazing view! 😍',
      'Living my best life ✨',
      'Weekend vibes 🎉',
      'Feeling blessed 🙏',
