@Composable
fun InstagramCloneApp() {
    var currentScreen by remember { mutableStateOf<Screen>(Screen.Feed) }

    val threads = remember {
        mutableStateListOf(
            ChatThread(
                user = ChatUser(
                    id = "u1",
                    username = "noirwaves",
                    avatarUrl = "https://picsum.photos/seed/dm_u1/100/100",
                    isOnline = true
                ),
                messages = listOf(
                    ChatMessage("m1", "yo did you post the new cover yet?", false, nowMinusMinutes(25)),
                    ChatMessage("m2", "not yet, still tweaking the mix a bit", true, nowMinusMinutes(22)),
                    ChatMessage("m3", "send it when it is up", false, nowMinusMinutes(19))
                )
            ),
            ChatThread(
                user = ChatUser(
                    id = "u2",
                    username = "filmgrain",
                    avatarUrl = "https://picsum.photos/seed/dm_u2/100/100",
                    isOnline = false
                ),
                messages = listOf(
                    ChatMessage("m4", "that last snippet looked great", false, nowMinusMinutes(130))
                )
            ),
            ChatThread(
                user = ChatUser(
                    id = "u3",
                    username = "cloudparlor",
                    avatarUrl = "https://picsum.photos/seed/dm_u3/100/100",
                    isOnline = true
                ),
                messages = listOf(
                    ChatMessage("m5", "want to collab on a dreamy acoustic track?", false, nowMinusMinutes(300)),
                    ChatMessage("m6", "yeah, send the key and bpm", true, nowMinusMinutes(290))
                )
            )
        )
    }

    fun updateThread(updated: ChatThread) {
        val index = threads.indexOfFirst { it.user.id == updated.user.id }
        if (index != -1) {
            threads[index] = updated
            val sorted = threads.sortedByDescending { it.messages.lastOrNull()?.timestampMillis ?: 0L }
            threads.clear()
            threads.addAll(sorted)
        }
    }

    when (val screen = currentScreen) {
        is Screen.Feed -> FeedScreen(
            onOpenCamera = { currentScreen = Screen.Camera },
            onOpenMessages = { currentScreen = Screen.Messages }
        )

        is Screen.Camera -> CameraScreen(
            onBack = { currentScreen = Screen.Feed }
        )

        is Screen.Messages -> MessagesScreen(
            threads = threads,
            onBack = { currentScreen = Screen.Feed },
            onOpenChat = { threadId -> currentScreen = Screen.Chat(threadId) }
        )

        is Screen.Chat -> {
            val thread = threads.firstOrNull { it.user.id == screen.threadId }
            if (thread != null) {
                ChatScreen(
                    thread = thread,
                    onBack = { currentScreen = Screen.Messages },
                    onThreadUpdated = ::updateThread
                )
            } else {
                currentScreen = Screen.Messages
            }
        }
    }
}

