    val captions = remember {
        listOf(
            "A quiet moment somewhere far away.",
            "Chasing light and losing track of time.",
            "Nothing special, just liked the colors.",
            "This one felt like a movie frame.",
            "Tiny details make the whole day better.",
            "Collected another soft memory.",
            "Somewhere between noise and peace.",
            "The kind of day that writes itself.",
            "A little texture, a little chaos.",
            "Could stare at this for hours.",
            "Just passing through.",
            "The feed needed this vibe."
        )
    }

    val locations = remember {
        listOf(
            "Istanbul", "Amsterdam", "Berlin", "Tokyo",
            "New York", "Paris", "Seoul", "Copenhagen",
            "Prague", "Lisbon", "Vienna", "Oslo"
        )
    }

    val posts = remember { mutableStateListOf<Post>() }
    val listState = rememberLazyListState()

    var page by remember { mutableIntStateOf(1) }
    var isInitialLoading by remember { mutableStateOf(true) }
    var isRefreshing by remember { mutableStateOf(false) }
    var isLoadingMore by remember { mutableStateOf(false) }
    var feedVersion by remember { mutableLongStateOf(System.currentTimeMillis()) }

    val pageSize = 10

    suspend fun fetchPosts(pageToLoad: Int): List<Post> {
        delay(850)
        val startIndex = (pageToLoad - 1) * pageSize

        return List(pageSize) { index ->
            val globalIndex = startIndex + index
            val seed = "feed_${feedVersion}_p${pageToLoad}_i$globalIndex"

            Post(
                id = "post_$seed",
                username = usernames[globalIndex % usernames.size],
                location = locations[globalIndex % locations.size],
                caption = captions[globalIndex % captions.size],
                avatarUrl = "https://picsum.photos/seed/avatar_$seed/100/100",
                imageUrl = "https://picsum.photos/seed/$seed/900/1200",
                likes = Random.nextInt(80, 5000),
                minutesAgo = Random.nextInt(1, 300)
            )
        }
    }

    suspend fun refreshFeed() {
        if (isRefreshing) return
        isRefreshing = true
        feedVersion = System.currentTimeMillis()
        page = 1
        posts.clear()
        posts.addAll(fetchPosts(1))
        isRefreshing = false
    }

    suspend fun loadMore() {
        if (isInitialLoading || isRefreshing || isLoadingMore) return
        isLoadingMore = true
        val nextPage = page + 1
        posts.addAll(fetchPosts(nextPage))
        page = nextPage
        isLoadingMore = false
    }

    LaunchedEffect(Unit) {
        posts.clear()
        posts.addAll(fetchPosts(1))
        isInitialLoading = false
    }

    LaunchedEffect(listState.layoutInfo.visibleItemsInfo, posts.size) {
        val lastVisibleIndex = listState.layoutInfo.visibleItemsInfo.lastOrNull()?.index ?: 0
        if (posts.isNotEmpty() && lastVisibleIndex >= posts.lastIndex - 2) {
            loadMore()
        }
    }

    var refreshRequested by remember { mutableStateOf(false) }

    LaunchedEffect(refreshRequested) {
        if (refreshRequested) {
            refreshRequested = false
            refreshFeed()
        }
    }

    val pullRefreshState = rememberPullRefreshState(
        refreshing = isRefreshing,
        onRefresh = { refreshRequested = true }
    )

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.White)
            .pointerInput(Unit) {
                var totalDrag = 0f
                detectHorizontalDragGestures(
                    onHorizontalDrag = { _, dragAmount ->
                        totalDrag += dragAmount
                    },
                    onDragEnd = {
                        when {
                            totalDrag < -120f -> onOpenCamera()
                            totalDrag > 120f -> onOpenMessages()
                        }
                        totalDrag = 0f
                    },
                    onDragCancel = { totalDrag = 0f }
                )
            }
    ) {
        Scaffold(
            containerColor = Color.White,
            topBar = {
                TopAppBar(
                    modifier = Modifier.statusBarsPadding(),
                    title = {
                        Text(
                            text = "Instagram",
                            fontWeight = FontWeight.Bold,
                            color = Color.Black
                        )
                    },
                    actions = {
                        IconButton(onClick = onOpenCamera) {
                            Icon(
                                imageVector = Icons.Outlined.CameraAlt,
                                contentDescription = "Camera",
                                tint = Color.Black
                            )
                        }
                        IconButton(onClick = onOpenMessages) {
                            Icon(
                                imageVector = Icons.Outlined.Send,
                                contentDescription = "Messages",
                                tint = Color.Black
                            )
                        }
                    }
                )
            },
            bottomBar = {
                NavigationBar(
                    containerColor = Color.White,
                    modifier = Modifier.navigationBarsPadding()
                ) {
                    NavigationBarItem(
                        selected = true,
                        onClick = {},
                        icon = { Icon(Icons.Outlined.Home, contentDescription = "Home") },
                        label = {}
                    )
                    NavigationBarItem(
                        selected = false,
                        onClick = {},
                        icon = { Icon(Icons.Outlined.Search, contentDescription = "Search") },
                        label = {}
                    )
                    NavigationBarItem(
                        selected = false,
                        onClick = {},
                        icon = { Icon(Icons.Outlined.AddBox, contentDescription = "Add") },
                        label = {}
                    )
                    NavigationBarItem(
                        selected = false,
                        onClick = {},
                        icon = { Icon(Icons.Outlined.VideoLibrary, contentDescription = "Reels") },
                        label = {}
                    )
                    NavigationBarItem(
                        selected = false,
                        onClick = {},
                        icon = { Icon(Icons.Outlined.PersonOutline, contentDescription = "Profile") },
                        label = {}
                    )
                }
            }
        ) { paddingValues ->
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues)
                    .pullRefresh(pullRefreshState)
            ) {
                if (isInitialLoading) {
                    Box(
                        modifier = Modifier.fillMaxSize(),
                        contentAlignment = Alignment.Center
                    ) {
                        CircularProgressIndicator()
                    }
                } else {
                    LazyColumn(
                        state = listState,
                        modifier = Modifier.fillMaxSize()
                    ) {
                        itemsIndexed(
                            items = posts,
                            key = { _, post -> post.id }
                        ) { index, post ->
                            PostCard(post = post)

                            if (index == posts.lastIndex && isLoadingMore) {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 24.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    CircularProgressIndicator()
                                }
                            }
                        }
                    }
                }

                PullRefreshIndicator(
                    refreshing = isRefreshing,
                    state = pullRefreshState,
                    modifier = Modifier.align(Alignment.TopCenter)
                )
            }
        }
    }
}

@Composable
fun CameraScreen(
    onBack: () -> Unit
) {
    BackHandler(onBack = onBack)

    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current

    val hasCameraPermission = remember {
        ContextCompat.checkSelfPermission(
            context,
            Manifest.permission.CAMERA
        ) == PackageManager.PERMISSION_GRANTED
    }

    var lensFacing by remember { mutableIntStateOf(CameraSelector.LENS_FACING_BACK) }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
            .pointerInput(lensFacing) {
                var totalDrag = 0f
                detectHorizontalDragGestures(
                    onHorizontalDrag = { _, dragAmount ->
                        totalDrag += dragAmount
                    },
                    onDragEnd = {
                        if (totalDrag > 120f) onBack()
                        totalDrag = 0f
                    },
                    onDragCancel = { totalDrag = 0f }
                )
            }
    ) {
        if (!hasCameraPermission) {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                Text("Camera permission not granted.", color = Color.White)
            }
        } else {
            AndroidView(
                modifier = Modifier.fillMaxSize(),
                factory = { ctx ->
                    PreviewView(ctx).apply {
                        implementationMode = PreviewView.ImplementationMode.COMPATIBLE
                        scaleType = PreviewView.ScaleType.FILL_CENTER
                    }
                },
                update = { previewView ->
                    val cameraProviderFuture = ProcessCameraProvider.getInstance(context)
                    cameraProviderFuture.addListener(
                        {
                            val cameraProvider = cameraProviderFuture.get()
                            val preview = Preview.Builder().build().also {
                                it.surfaceProvider = previewView.surfaceProvider
                            }

                            val cameraSelector = CameraSelector.Builder()
                                .requireLensFacing(lensFacing)
                                .build()

                            try {
                                cameraProvider.unbindAll()
                                cameraProvider.bindToLifecycle(
                                    lifecycleOwner,
                                    cameraSelector,
                                    preview
                                )
                            } catch (_: Exception) {
                            }
                        },
                        ContextCompat.getMainExecutor(context)
                    )
                }
            )

            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .navigationBarsPadding()
                    .padding(16.dp),
                verticalArrangement = Arrangement.SpaceBetween
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    IconButton(onClick = onBack) {
                        Icon(
                            imageVector = Icons.Outlined.ArrowBack,
                            contentDescription = "Back",
                            tint = Color.White
                        )
                    }

                    Text(
                        text = "Camera",
                        color = Color.White,
                        fontWeight = FontWeight.Bold
                    )

                    IconButton(
                        onClick = {
                            lensFacing = if (lensFacing == CameraSelector.LENS_FACING_BACK) {
                                CameraSelector.LENS_FACING_FRONT
                            } else {
                                CameraSelector.LENS_FACING_BACK
                            }
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Cached,
                            contentDescription = "Switch Camera",
                            tint = Color.White
                        )
                    }
                }

                Box(
                    modifier = Modifier.fillMaxWidth(),
                    contentAlignment = Alignment.Center
                ) {
                    Box(
                        modifier = Modifier
                            .size(76.dp)
                            .clip(CircleShape)
                            .background(Color.White)
                    )
                }
            }
        }
    }

    DisposableEffect(Unit) {
        onDispose {
            val cameraProviderFuture = ProcessCameraProvider.getInstance(context)
            cameraProviderFuture.addListener(
                {
                    try {
                        cameraProviderFuture.get().unbindAll()
                    } catch (_: Exception) {
                    }
                },
                ContextCompat.getMainExecutor(context)
            )
        }
    }
}

