                LazyColumn(
                    modifier = Modifier.weight(1f),
                    reverseLayout = false
                ) {
                    itemsIndexed(
                        items = currentThread.messages,
                        key = { _, message -> message.id }
                    ) { _, message ->
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 12.dp, vertical = 4.dp),
                            contentAlignment = if (message.isMe) Alignment.CenterEnd else Alignment.CenterStart
                        ) {
                            Column(
                                modifier = Modifier
                                    .clip(MaterialTheme.shapes.large)
                                    .background(
                                        if (message.isMe) Color(0xFF1976D2) else Color(0xFFEAEAEA)
                                    )
                                    .padding(horizontal = 14.dp, vertical = 10.dp)
                            ) {
                                Text(
                                    text = message.text,
                                    color = if (message.isMe) Color.White else Color.Black
                                )
                                Spacer(modifier = Modifier.size(4.dp))
                                Text(
                                    text = formatMessageTime(message.timestampMillis),
                                    color = if (message.isMe) Color.White.copy(alpha = 0.7f) else Color.Gray
                                )
                            }
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(12.dp),
                    verticalAlignment = Alignment.Bottom
                ) {
                    OutlinedTextField(
                        value = input,
                        onValueChange = { input = it },
                        modifier = Modifier.weight(1f),
                        placeholder = { Text("Message...") },
                        maxLines = 5
                    )

                    Spacer(modifier = Modifier.width(8.dp))

                    IconButton(
                        onClick = {
                            val text = input.trim()
                            if (text.isEmpty()) return@IconButton

                            val sentMessage = ChatMessage(
                                id = System.currentTimeMillis().toString(),
                                text = text,
                                isMe = true,
                                timestampMillis = System.currentTimeMillis()
                            )

                            currentThread = currentThread.copy(
                                messages = currentThread.messages + sentMessage
                            )
                            input = ""

                            scope.launch {
                                delay((900..1800).random().toLong())
                                val reply = ChatMessage(
                                    id = "${System.currentTimeMillis()}_reply",
                                    text = autoReplies.random(),
                                    isMe = false,
                                    timestampMillis = System.currentTimeMillis()
                                )
                                currentThread = currentThread.copy(
                                    messages = currentThread.messages + reply
                                )
                                onThreadUpdated(currentThread)
                            }

                            onThreadUpdated(currentThread)
                        }
                    ) {
                        Icon(
                            imageVector = Icons.Outlined.Send,
                            contentDescription = "Send",
                            tint = Color(0xFF1976D2)
                        )
                    }
                }
            }
        }
    }
