fun nowMinusMinutes(minutes: Int): Long {
    return System.currentTimeMillis() - minutes * 60_000L
}

fun formatChatTime(timestampMillis: Long): String {
    val diff = System.currentTimeMillis() - timestampMillis
    val minutes = diff / 60_000L
    val hours = diff / 3_600_000L
    val days = diff / 86_400_000L

    return when {
        minutes < 1 -> "now"
        minutes < 60 -> "${minutes}m"
        hours < 24 -> "${hours}h"
        else -> "${days}d"
    }
}

fun formatMessageTime(timestampMillis: Long): String {
    val calendar = java.util.Calendar.getInstance().apply {
        timeInMillis = timestampMillis
    }
    val hour24 = calendar.get(java.util.Calendar.HOUR_OF_DAY)
    val minute = calendar.get(java.util.Calendar.MINUTE)
    val hour12 = if (hour24 % 12 == 0) 12 else hour24 % 12
    val amPm = if (hour24 >= 12) "PM" else "AM"
    return "$hour12:${minute.toString().padStart(2, '0')} $amPm"
}

