@OptIn(ExperimentalMaterial3Api::class, ExperimentalPermissionsApi::class)
@Composable
fun InstagramHomePage() {
    val viewModel: PostViewModel = viewModel()
    val pagingItems = viewModel.postsFlow.collectAsLazyPagingItems()
    val listState = rememberLazyListState()
    var showCameraOverlay by remember { mutableStateOf(false) }
    var showMessagesView by remember { mutableStateOf(false) }
    var capturedImageUri by remember { mutableStateOf<Uri?>(null) }
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    // Direct Messages state
    val messagesViewModel: MessagesViewModel = viewModel()
    val messages by messagesViewModel.messages.collectAsState()
    val conversations by messagesViewModel.conversations.collectAsState()
    var currentConversation by remember { mutableStateOf<String?>("user2") }
    var messageText by remember { mutableStateOf("") }

    // Camera permission launcher
    val permissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestPermission()
    ) { isGranted ->
        if (isGranted) {
            launchCamera(context) { uri ->
                capturedImageUri = uri
                showCameraOverlay = true
                showMessagesView = false
                scope.launch {
                    delay(3000)
                    showCameraOverlay = false
                }
            }
        }
    }

    // Swipe gesture handling
    var dragOffset by remember { mutableStateOf(0f) }

    fun openCamera() {
        when {
            ContextCompat.checkSelfPermission(
                context,
                Manifest.permission.CAMERA
            ) == PackageManager.PERMISSION_GRANTED -> {
                launchCamera(context) { uri ->
                    capturedImageUri = uri
                    showCameraOverlay = true
                    showMessagesView = false
                    scope.launch {
                        delay(3000)
                        showCameraOverlay = false
                    }
                }
            }
            else -> {
                permissionLauncher.launch(Manifest.permission.CAMERA)
            }
        }
    }

    fun openDirectMessages() {
        showMessagesView = true
        showCameraOverlay = false
        if (currentConversation != null) {
            messagesViewModel.loadMessages(currentConversation!!)
        }
    }

    fun closeMessages() {
        showMessagesView = false
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .pointerInput(Unit) {
                detectHorizontalDragGestures(
                    onDragEnd = {
                        when {
                            dragOffset < -100f -> { // Swipe left
                                if (showMessagesView) {
                                    closeMessages()
                                } else {
                                    openCamera()
                                }
                            }
                            dragOffset > 100f -> { // Swipe right
                                if (showCameraOverlay) {
                                    showCameraOverlay = false
                                } else {
                                    openDirectMessages()
                                }
                            }
                        }
                        dragOffset = 0f
                    },
                    onDragCancel = { dragOffset = 0f },
                    onHorizontalDrag = { change, dragAmount ->
                        change.consume()
                        dragOffset += dragAmount
                    }
                )
            }
    ) {
        if (!showMessagesView) {
            // Main Feed
            Scaffold(
                topBar = {
                    TopAppBar(
                        title = {
                            Text(
                                "Instagram Clone",
                                fontSize = 28.sp,
                                fontWeight = FontWeight.Normal,
                                color = Color.White,
                                letterSpacing = (-0.5).sp
                            )
                        },
                        actions = {
                            IconButton(onClick = {}) {
                                Icon(Icons.outlined.FavoriteBorder, tint = Color.White)
                            }
                            IconButton(onClick = { openDirectMessages() }) {
                                Icon(Icons.outlined.Message, tint = Color.White)
                            }
                        },
                        colors = TopAppBarDefaults.topAppBarColors(
                            containerColor = Color.Black,
                            scrolledContainerColor = Color.Black
                        )
                    )
                },
                bottomBar = {
                    NavigationBar(
                        containerColor = Color.Black,
                        tonalElevation = 0.dp
                    ) {
                        listOf(
                            Icons.Filled.Home to "Home",
                            Icons.Outlined.Search to "Search",
                            Icons.Outlined.AddBox to "Create",
                            Icons.Outlined.FavoriteBorder to "Activity",
                            Icons.Outlined.Person to "Profile"
                        ).forEach { (icon, label) ->
                            NavigationBarItem(
                                icon = { Icon(icon, tint = Color.White) },
                                label = { Text(label, color = Color.White, fontSize = 10.sp) },
                                selected = false,
                                onClick = {},
                                colors = NavigationBarItemDefaults.colors(
                                    selectedIconColor = Color.White,
                                    unselectedIconColor = Color.Gray,
                                    selectedTextColor = Color.White,
                                    unselectedTextColor = Color.Gray
                                )
                            )
                        }
                    }
                }
            ) { paddingValues ->
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(paddingValues)
                ) {
                    LazyColumn(
                        state = listState,
                        modifier = Modifier.fillMaxSize()
                    ) {
                        // Stories section
                        item {
                            StoriesSection()
                        }

                        // Posts with pagination
                        items(
                            count = pagingItems.itemCount,
                            key = pagingItems.itemKey { it.id }
                        ) { index ->
                            val post = pagingItems[index]
                            post?.let {
                                PostCard(post = it)
                            }
                        }

                        // Loading indicator for pagination
                        if (pagingItems.loadState.append is LoadState.Loading) {
                            item {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    CircularProgressIndicator(color = Color.White)
                                }
                            }
                        }

                        // Error handling
                        val error = pagingItems.loadState.append as? LoadState.Error
                        if (error != null) {
                            item {
                                Box(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(16.dp),
                                    contentAlignment = Alignment.Center
                                ) {
                                    Column(
                                        horizontalAlignment = Alignment.CenterHorizontally
                                    ) {
                                        Text(
                                            "Error: ${error.error.message}",
                                            color = Color.Red
                                        )
                                        Button(
                                            onClick = { pagingItems.retry() },
                                            colors = ButtonDefaults.buttonColors(
                                                containerColor = Color.White
                                            )
                                        ) {
                                            Text("Retry", color = Color.Black)
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Pull to refresh indicator
                    if (pagingItems.loadState.refresh is LoadState.Loading) {
                        Box(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(top = 50.dp),
                            contentAlignment = Alignment.TopCenter
                        ) {
                            CircularProgressIndicator(color = Color.White)
                        }
                    }

                    // Swipe instruction overlay
                    if (!showCameraOverlay && capturedImageUri == null) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(bottom = 100.dp),
                            contentAlignment = Alignment.BottomCenter
                        ) {
                            Card(
                                modifier = Modifier
                                    .padding(horizontal = 20.dp)
                                    .fillMaxWidth(),
                                colors = CardDefaults.cardColors(
                                    containerColor = Color.Black.copy(alpha = 0.8f)
                                ),
                                shape = RoundedCornerShape(20.dp)
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(horizontal = 16.dp, vertical = 10.dp),
                                    horizontalArrangement = Arrangement.SpaceEvenly,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(Icons.Swipe, tint = Color.White, modifier = Modifier.size(20.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(
                                            "Left: Camera",
                                            color = Color.White.copy(alpha = 0.9f),
                                            fontSize = 12.sp
                                        )
                                    }
                                    Box(
                                        modifier = Modifier
                                            .width(1.dp)
                                            .height(20.dp)
                                            .background(Color.White.copy(alpha = 0.3f))
                                    )
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Icon(Icons.Swipe, tint = Color.White, modifier = Modifier.size(20.dp))
                                        Spacer(modifier = Modifier.width(4.dp))
                                        Text(
                                            "Right: DMs",
                                            color = Color.White.copy(alpha = 0.9f),
                                            fontSize = 12.sp
                                        )
                                    }
                                }
                            }
                        }
                    }

                    // Camera overlay when image is captured
                    if (showCameraOverlay && capturedImageUri != null) {
                        val bitmap = remember(capturedImageUri) {
                            try {
                                val inputStream = context.contentResolver.openInputStream(capturedImageUri!!)
                                BitmapFactory.decodeStream(inputStream)?.asImageBitmap()
                            } catch (e: Exception) {
                                null
                            }
                        }

                        bitmap?.let {
                            Box(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .background(Color.Black.copy(alpha = 0.95f))
                            ) {
                                Column(
                                    modifier = Modifier
                                        .fillMaxSize()
                                        .padding(20.dp),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    Card(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .height(500.dp),
                                        shape = RoundedCornerShape(10.dp),
                                        colors = CardDefaults.cardColors(containerColor = Color.Transparent)
                                    ) {
                                        Image(
                                            bitmap = it,
                                            contentDescription = "Captured Photo",
                                            modifier = Modifier.fillMaxSize(),
                                            contentScale = ContentScale.Crop
                                        )
                                    }

                                    Spacer(modifier = Modifier.height(20.dp))

                                    Text(
                                        "Photo Captured!",
                                        style = TextStyle(
                                            color = Color.White,
                                            fontSize = 20.sp,
                                            fontWeight = FontWeight.Bold
                                        )
                                    )

                                    Spacer(modifier = Modifier.height(10.dp))

                                    Text(
                                        "Swipe left again to take another photo",
                                        color = Color.Gray,
                                        fontSize = 14.sp
                                    )

                                    Spacer(modifier = Modifier.height(20.dp))

                                    Button(
                                        onClick = { showCameraOverlay = false },
                                        colors = ButtonDefaults.buttonColors(
                                            containerColor = Color.Blue
                                        )
                                    ) {
                                        Text("Close", color = Color.White)
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            // Direct Messages View
            DirectMessagesView(
                conversations = conversations,
                currentConversation = currentConversation,
                messages = messages,
                messageText = messageText,
                onConversationSelected = { userId ->
                    currentConversation = userId
                    messagesViewModel.loadMessages(userId)
                },
                onMessageTextChange = { messageText = it },
                onSendMessage = {
                    if (messageText.isNotBlank()) {
                        messagesViewModel.sendMessage(currentConversation!!, messageText)
                        messageText = ""
                    }
                },
                onClose = { closeMessages() }
            )
        }
    }
}

@Composable
fun DirectMessagesView(
    conversations: List<Conversation>,
    currentConversation: String?,
    messages: List<Message>,
    messageText: String,
    onConversationSelected: (String) -> Unit,
    onMessageTextChange: (String) -> Unit,
    onSendMessage: () -> Unit,
    onClose: () -> Unit
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Row(
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        IconButton(onClick = onClose) {
                            Icon(Icons.ArrowBack, tint = Color.White)
                        }
                        Spacer(modifier = Modifier.width(8.dp))
                        val currentConv = conversations.find { it.userId == currentConversation }
                        if (currentConv != null) {
                            CircleAvatar(
                                radius = 16.dp,
                                painter = rememberAsyncImagePainter(currentConv.senderImage)
                            )
                            Spacer(modifier = Modifier.width(12.dp))
                            Text(
                                currentConv.senderName,
                                color = Color.White,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                },
                actions = {
                    IconButton(onClick = {}) {
                        Icon(Icons.VideocamOutlined, tint = Color.White)
                    }
                    IconButton(onClick = {}) {
                        Icon(Icons.CallOutlined, tint = Color.White)
                    }
                    IconButton(onClick = {}) {
                        Icon(Icons.InfoOutline, tint = Color.White)
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = Color.Black
                )
            )
        }
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
        ) {
            // Conversation list
            LazyRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(100.dp)
                    .background(Color.Black),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 8.dp)
            ) {
                items(conversations) { conversation ->
                    ConversationAvatar(
                        conversation = conversation,
                        isSelected = currentConversation == conversation.userId,
                        onSelect = { onConversationSelected(conversation.userId) }
                    )
                }
            }

            // Messages area
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .weight(1f),
                reverseLayout = true
            ) {
                items(messages.reversed()) { message ->
                    MessageBubble(message = message)
                }
            }

            // Message input
            MessageInput(
                messageText = messageText,
                onMessageTextChange = onMessageTextChange,
                onSendMessage = onSendMessage
            )
        }
    }
}

@Composable
fun ConversationAvatar(
    conversation: Conversation,
    isSelected: Boolean,
    onSelect: () -> Unit
) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = Modifier
            .width(70.dp)
            .clickable { onSelect() }
    ) {
        Box(
            modifier = Modifier
                .size(56.dp)
                .then(
                    if (isSelected) {
                        Modifier.border(2.dp, Color.Blue, CircleShape)
                    } else {
                        Modifier
                    }
                )
        ) {
            CircleAvatar(
                radius = 28.dp,
                painter = rememberAsyncImagePainter(conversation.senderImage)
            )
        }
        Text(
            text = conversation.senderName.split(" ").first(),
            color = if (isSelected) Color.Blue else Color.White,
            fontSize = 11.sp,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@Composable
fun MessageBubble(message: Message) {
    val isMe = message.isSentByMe
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 4.dp, horizontal = 12.dp),
        horizontalArrangement = if (isMe) Arrangement.End else Arrangement.Start
    ) {
        if (!isMe) {
            CircleAvatar(
                radius = 16.dp,
                painter = rememberAsyncImagePainter(message.senderImage)
            )
            Spacer(modifier = Modifier.width(8.dp))
        }
        Column(
            modifier = Modifier
                .widthIn(max = 250.dp)
                .background(
                    color = if (isMe) Color.Blue else Color(0xFF262626),
                    shape = RoundedCornerShape(20.dp)
                )
                .padding(horizontal = 12.dp, vertical = 8.dp)
        ) {
            if (!isMe) {
                Text(
                    text = message.senderName,
                    color = Color.White.copy(alpha = 0.7f),
                    fontSize = 10.sp,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.height(2.dp))
            }
            Text(
                text = message.text,
                color = Color.White,
                fontSize = 14.sp
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = formatTime(message.timestamp),
                color = Color.White.copy(alpha = 0.5f),
                fontSize = 10.sp
            )
        }
        if (isMe) {
            Spacer(modifier = Modifier.width(8.dp))
            CircleAvatar(
                radius = 16.dp,
                backgroundColor = Color(0xFF262626),
                modifier = Modifier.clip(CircleShape)
            ) {
                Icon(Icons.Person, tint = Color.White, modifier = Modifier.size(20.dp))
            }
        }
    }
}

@Composable
fun MessageInput(
    messageText: String,
    onMessageTextChange: (String) -> Unit,
    onSendMessage: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color(0xFF121212))
            .padding(horizontal = 12.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        IconButton(onClick = {}) {
            Icon(Icons.AddCircleOutline, tint = Color.White)
        }
        TextField(
            value = messageText,
            onValueChange = onMessageTextChange,
            modifier = Modifier.weight(1f),
            placeholder = { Text("Message...", color = Color.Gray) },
            textStyle = TextStyle(color = Color.White),
            colors = TextFieldDefaults.colors(
                focusedContainerColor = Color.Transparent,
                unfocusedContainerColor = Color.Transparent,
                focusedIndicatorColor = Color.Transparent,
                unfocusedIndicatorColor = Color.Transparent
            ),
            singleLine = true
        )
        IconButton(
            onClick = onSendMessage,
            enabled = messageText.isNotBlank()
        ) {
            Icon(
                Icons.Send,
                tint = if (messageText.isNotBlank()) Color.Blue else Color.Gray
            )
        }
    }
}

